const x = $input.first().json;
const parse = (v) => typeof v === 'string' ? JSON.parse(v) : v;
return [{ json: { ...x, groups: parse(x.groups), counterfactual_tests: parse(x.counterfactual_tests), policy: parse(x.policy), decision_context: parse(x.decision_context) } }];

const source = $input.first().json;
const policy = source.policy || {};
const groups = Array.isArray(source.groups) ? source.groups : [];
const tests = Array.isArray(source.counterfactual_tests) ? source.counterfactual_tests : [];
const ratio = (a, b) => Number.isFinite(Number(a)) && Number.isFinite(Number(b)) && Number(b) > 0 ? Number(a) / Number(b) : null;
const gap = (values) => { const x = values.filter(Number.isFinite); return x.length >= 2 ? Math.max(...x) - Math.min(...x) : null; };
const findings = [];
const metrics = { groups: [], gaps: {} };
const minN = Number(policy.min_group_n ?? 30);
for (const g of groups) {
  const tp = Number(g.true_positive), fn = Number(g.false_negative), fp = Number(g.false_positive), tn = Number(g.true_negative);
  const n = Number(g.n);
  metrics.groups.push({ name: g.name, n, acceptance_rate: ratio(g.accepted, n), tpr: ratio(tp, tp + fn), fpr: ratio(fp, fp + tn) });
  if (!Number.isFinite(n) || n < minN) findings.push({ code: 'SMALL_OR_INVALID_GROUP', severity: 'critical', group: g.name });
}
metrics.gaps = { acceptance_gap: gap(metrics.groups.map(g => g.acceptance_rate)), tpr_gap: gap(metrics.groups.map(g => g.tpr)), fpr_gap: gap(metrics.groups.map(g => g.fpr)) };
const limits = { acceptance_gap: Number(policy.max_acceptance_gap ?? 0.10), tpr_gap: Number(policy.max_tpr_gap ?? 0.10), fpr_gap: Number(policy.max_fpr_gap ?? 0.10) };
for (const [key, value] of Object.entries(metrics.gaps)) if (value !== null && value > limits[key]) findings.push({ code: key.toUpperCase() + '_EXCEEDED', severity: 'critical', observed: value, limit: limits[key] });
const inconsistent = tests.filter(t => t && t.consistent === false).length;
if (policy.require_counterfactual_consistency !== false && tests.length === 0) findings.push({ code: 'NO_COUNTERFACTUAL_TESTS', severity: 'warning' });
if (inconsistent > 0) findings.push({ code: 'COUNTERFACTUAL_INCONSISTENCY', severity: 'critical', count: inconsistent });
const critical = findings.filter(f => f.severity === 'critical').length;
const warning = findings.filter(f => f.severity === 'warning').length;
const highRisk = ['high', 'critical'].includes(String(source.risk_level).toLowerCase());
const human = critical > 0 || (highRisk && policy.high_risk_requires_human_review !== false);
return [{ json: { ...source, decision: human ? 'HUMAN_REVIEW' : warning > 0 ? 'HOLD' : 'AUTO_PASS', gate_pass: !human && warning === 0, human_review_required: human, metrics, findings, counterfactual_summary: { tested: tests.length, inconsistent }, evidence_refs: ['audit://' + source.audit_id], created_at: new Date().toISOString() } }];
